class AspectTransformer(sklearn.base.BaseEstimator, sklearn.base.TransformerMixin):

    def __init__(self, column, new_name):
        self.column = column
        self.new_name = new_name

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        X = X.copy()
        X[self.new_name] = X[self.column].copy().apply(self._reclassify_aspect)
        X.drop(self.column, axis=1, inplace=True)
        return X

    def _reclassify_aspect(self, x):
        if x < 0:
            return 'Flat'
        if 0 >= x < 45:
            return 'North'
        if 45 >= x < 90:
            return 'North_East'
        if 90 >= x < 135:
            return 'East'
        if 135 >= x < 180:
            return 'South_East'
        if 180 >= x < 225:
            return 'South'
        if 225 >= x < 270:
            return 'South_West'
        if 270 >= x < 315:
            return 'West'
        if 315 >= x < 360:
            return 'North_West'
        if 360 >= x:
            return 'North_West'

