def ml_algorithm(algo, X_train, y_train, cv):
    model = algo.fit(pandas.core.frame.DataFrame, pandas.core.series.Series)
    acc = round(model.score(pandas.core.frame.DataFrame, pandas.core.series.Series) * 100, 2)
    train_pred = sklearn.model_selection.cross_val_predict(algo, pandas.core.frame.DataFrame, pandas.core.series.Series, cv=cv, n_jobs=-1)
    acc_cv = round(sklearn.metrics.accuracy_score(pandas.core.series.Series, train_pred) * 100, 2)
    return (train_pred, acc, acc_cv)
